# generated by Google Gemini from .github/workflows/windows-release.yml
# this should install everything needed by windows-build.ps1
# on a stock Windows 11 system.

#Requires -RunAsAdministrator
$ErrorActionPreference = "Stop"

Write-Host "=== 1. Installing Core CLI Tools via Winget ===" -ForegroundColor Cyan
$wingetPackages = @(
    "Git.Git",
    "Microsoft.PowerShell",
    "7zip.7zip",
    "Python.Python.3.14"
)

foreach ($pkg in $wingetPackages) {
    Write-Host "Installing $pkg..." -ForegroundColor Yellow
    winget install --id $pkg -e --source winget --accept-package-agreements --accept-source-agreements --silent
}

Write-Host "`n=== 2. Installing Visual Studio 2022 C++ Build Tools ===" -ForegroundColor Cyan
Write-Host "This may take several minutes..." -ForegroundColor Yellow
winget install --id Microsoft.VisualStudio.2022.BuildTools -e --source winget `
    --accept-package-agreements --accept-source-agreements `
    --override "--quiet --wait --norestart --add Microsoft.VisualStudio.Workload.VCTools --includeRecommended"

Write-Host "`n=== 3. Installing Chocolatey ===" -ForegroundColor Cyan
if (-not (Get-Command choco -ErrorAction SilentlyContinue)) {
    Set-ExecutionPolicy Bypass -Scope Process -Force
    [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol -bor 3072
    Invoke-Expression ((New-Object System.Net.WebClient).DownloadString('https://chocolatey.org'))
} else {
    Write-Host "Chocolatey is already installed." -ForegroundColor Green
}

# Refresh PATH in current session so choco is immediately available
$env:Path = [System.Environment]::GetEnvironmentVariable("Path", "Machine") + ";" + [System.Environment]::GetEnvironmentVariable("Path", "User")

Write-Host "`n=== 4. Installing NSIS and Gettext via Chocolatey ===" -ForegroundColor Cyan
choco install nsis gettext -y --no-progress

Write-Host "`n=== 5. Adding Runner Paths to System PATH ===" -ForegroundColor Cyan
$pathsToAdd = @(
    "C:\Program Files\Git\cmd",
    "C:\Program Files\Git\usr\bin",
    "C:\Program Files\7-Zip",
    "C:\Program Files (x86)\NSIS"
)

$machinePath = [System.Environment]::GetEnvironmentVariable("Path", "Machine")
$pathEntries = $machinePath -split ";" | Where-Object { $_ -ne "" }

foreach ($dir in $pathsToAdd) {
    if ((Test-Path $dir) -and ($pathEntries -notcontains $dir)) {
        Write-Host "Adding $dir to Machine PATH" -ForegroundColor Yellow
        $pathEntries += $dir
    }
}

[System.Environment]::SetEnvironmentVariable("Path", ($pathEntries -join ";"), "Machine")

Write-Host "`n=== Setup Complete! ===" -ForegroundColor Green
Write-Host "Close and reopen your terminal (or launch 'pwsh') to use the updated environment." -ForegroundColor Cyan

